ICON_NAMES = sorted(_P)


def icon(name, size=18, color="currentColor", stroke=2.0, cls=""):
    """Return an inline <svg> string. Written on ONE line so Streamlit markdown never breaks it."""
    body = _P.get(name, _P["info"])
    c = f' class="{cls}"' if cls else ""
    return (f'<svg{c} xmlns="http://www.w3.org/2000/svg" width="{size}" height="{size}" '
            f'viewBox="0 0 24 24" fill="none" stroke="{color}" stroke-width="{stroke}" '
            f'stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{body}</svg>')


def icon_uri(name, color="#cbd5e1", stroke=2.0):
    """Icon as a CSS data-URI, used for sidebar navigation icons."""
    svg = icon(name, 24, color, stroke)
    return "data:image/svg+xml;utf8," + quote(svg, safe="/:=,;()' ")
